def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 95:
                aggressive_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_count += 1

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    low_supply = supply <= 17
    high_supply = supply >= 22

    critical = hp <= 2 or no_water_days >= 2
    urgent = hp <= 4 or no_water_days >= 1

    target = DAILY_SALARY * 0.28

    if critical:
        target = DAILY_SALARY * 1.18
    elif urgent:
        target = DAILY_SALARY * 0.95
    else:
        if low_supply:
            target = DAILY_SALARY * 0.72
        elif high_supply:
            target = DAILY_SALARY * 0.22
        else:
            target = DAILY_SALARY * 0.42

        if aggressive_count >= 2:
            target *= 0.82
        elif highest_prev_bid > 0:
            if highest_prev_bid < 80:
                target = max(target, highest_prev_bid + 2.0)
            elif highest_prev_bid < 100:
                target = max(target, highest_prev_bid * 0.92)
            else:
                target = min(target, DAILY_SALARY * 0.55)

        if weak_count > 0 and not low_supply:
            target *= 0.9

    if day >= 8:
        if urgent:
            target = max(target, DAILY_SALARY * 0.98)
        else:
            target *= 1.08

    if budget < DAILY_SALARY * 1.2:
        if not urgent:
            target = min(target, budget * 0.55)
        else:
            target = min(max(target, budget * 0.7), budget)

    if hp >= 8 and no_water_days == 0 and aggressive_count >= 2 and not low_supply:
        target = min(target, DAILY_SALARY * 0.2)

    target = max(0.0, min(float(budget), float(target)))
    return float(round(target, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    budget = my_status['budget']
    hp = my_status['hp']
    supply = day_context['supply']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])

    base_bid = DAILY_SALARY * 0.5  # 45
    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev > DAILY_SALARY * 0.8:  # >72
            base_bid = DAILY_SALARY * 0.9  # 81

    # Adjust for low HP
    if hp < 3:
        base_bid = DAILY_SALARY * 0.95  # 85.5

    # Adjust for high supply (lower bid)
    if supply > 20:
        base_bid *= 0.85

    bid = min(budget, max(0, base_bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    num_available_water_units = int(day_context['supply'] // WATER_REQ)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    bid = 0.0

    if my_status['hp'] <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        total_contenders = num_alive_opponents + 1
        if total_contenders > num_available_water_units:
            bid = DAILY_SALARY * 0.85
        else:
            bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 2.0)
    else:
        total_contenders = num_alive_opponents + 1

        if total_contenders > num_available_water_units:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                bid = highest_prev_bid + (DAILY_SALARY * 0.05)
            elif highest_prev_bid >= DAILY_SALARY * 0.6:
                bid = highest_prev_bid + (DAILY_SALARY * 0.03)
            else:
                bid = DAILY_SALARY * 0.65
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.5:
                bid = highest_prev_bid * 0.9
            elif highest_prev_bid >= DAILY_SALARY * 0.2:
                bid = max(DAILY_SALARY * 0.3, highest_prev_bid + 1.0)
            else:
                bid = DAILY_SALARY * 0.2

    final_bid = max(1.0, bid)
    final_bid = min(my_status['budget'], final_bid)

    return final_bid
